export function mountDobiOrders(root,{basePath,styles,initialView='orders',settingsOnly=false,onNavigate}={}) {
  let disposed=false;const listeners=[];
  const nativeDocument=globalThis.document;
  const document={querySelector:s=>root.querySelector(s),querySelectorAll:s=>root.querySelectorAll(s),addEventListener:(...args)=>{root.addEventListener(...args);listeners.push(args)},createElement:(...args)=>nativeDocument.createElement(...args),createTextNode:(...args)=>nativeDocument.createTextNode(...args),body:root,title:''};
  const window={print:()=>{const source=root.querySelector('.print-only');if(!source)return;const printable=nativeDocument.createElement('div');printable.className='dobi-print-root';printable.innerHTML=source.innerHTML;nativeDocument.body.append(printable);nativeDocument.body.classList.add('dobi-print-mode');try{globalThis.window.print();}finally{nativeDocument.body.classList.remove('dobi-print-mode');printable.remove();}}};
  const scopedUrl=url=>typeof url==='string'&&url.startsWith('/api/')?basePath+url.slice(4):url;
  const fetch=(url,options)=>globalThis.fetch(scopedUrl(url),{...options,credentials:'same-origin'});
  root.innerHTML="<div class=\"dobi-root\"><a class=\"brand\" hidden><span></span><span></span></a><div hidden><b id=\"crumb\"></b><span id=\"today\"></span></div><nav id=\"nav\" aria-label=\"주문 작업실\"><button data-view=\"overview\">요약</button><button class=\"active\" data-view=\"orders\">통합 주문 <small id=\"navTotal\">0</small></button><button data-view=\"claims\">클레임 <small id=\"navClaims\">0</small></button><button data-view=\"memos\">CS · 메모</button><button data-view=\"reports\">주문 통계</button><button data-view=\"forwarding\">배송대행 신청</button><button data-view=\"connections\">계정 연결</button><button data-view=\"settings\">작업실 설정</button><button id=\"refreshBtn\" aria-label=\"주문 새로고침\">↻</button></nav><main id=\"main\" aria-live=\"polite\"><p>주문 작업실을 준비하고 있습니다…</p></main><dialog id=\"dialog\"><div class=\"dialog-head\"><div><p class=\"eyebrow\" id=\"dialogKicker\"></p><h2 id=\"dialogTitle\"></h2></div><button id=\"closeDialog\" class=\"icon-btn\" aria-label=\"닫기\">×</button></div><div id=\"dialogBody\"></div></dialog><div id=\"toast\" role=\"status\"></div></div>";
  const sheet=nativeDocument.createElement("style");sheet.textContent=styles;root.prepend(sheet);
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n||0).toLocaleString('ko-KR')+'원';
const state={view:initialView,filters:{},page:1,limit:50,selected:new Set(),data:null,stats:null,boot:null};
let refreshSequence=0,searchTimer,toastTimer,importState;
const titles={orders:'통합 주문',overview:'한눈에 보기',claims:'클레임 관리',memos:'CS · 작업 메모',reports:'주문 통계',connections:'쇼핑몰 · 배송대행 연결',forwarding:'배송대행 신청',settings:'내 작업실 설정'};
async function api(url,data,method){const options={method:method||(data?'POST':'GET'),headers:{'X-Dobi-Token':state.boot?.token||''}};if(data!==undefined){options.headers['Content-Type']='application/json';options.body=JSON.stringify(data);}const response=await fetch(url,options);if(disposed)throw Error('화면을 닫았습니다.');let result;try{result=await response.json();}catch{throw Error('응답을 받지 못했습니다. 새로고침해주세요.');}if(!response.ok)throw Error(result.error||'처리하지 못했습니다.');return result;}
function toast(text,error=false){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').className='show'+(error?' error':'');toastTimer=setTimeout(()=>$('#toast').className='',error?7000:3500);}
async function run(fn){if(disposed)return;try{await fn();}catch(e){if(!disposed)toast(e.message,true);}}
function selectOptions(values,value,empty){return (empty!==undefined?`<option value="">${esc(empty)}</option>`:'')+values.map(v=>`<option value="${esc(v)}"${v===value?' selected':''}>${esc(v)}</option>`).join('');}
const tag=o=>`<span class="pill" data-status="${esc(o.status)}">${esc(o.status)}</span>${o.onHold?' <span class="pill hold">보류</span>':''}${o.demo?' <span class="pill demo">예제</span>':''}`;
function pageHead(title,description,actions=''){return `<div class="page-head"><div><p class="eyebrow">YOUR ORDER WORKSPACE</p><h2>${esc(title)}</h2><p class="subtitle">${esc(description)}</p></div><div class="head-actions">${actions}</div></div>`;}
function metrics(){const s=state.stats;return `<div class="metrics"><button class="metric" data-filter-status=""><div class="metric-label"><span>전체 주문 품목</span><span>▤</span></div><div class="metric-value">${s.total.toLocaleString()}<small>건</small></div><div class="metric-note">내 작업실에 등록한 전체 품목</div></button><button class="metric" data-filter-status="발송대기"><div class="metric-label"><span>발송 준비</span><span>↗</span></div><div class="metric-value">${(s.counts['신규']+s.counts['발송대기']).toLocaleString()}<small>건</small></div><div class="metric-note">신규 ${s.counts['신규']} · 발송대기 ${s.counts['발송대기']}</div></button><button class="metric" data-filter-hold><div class="metric-label"><span>보류 주문</span><span>Ⅱ</span></div><div class="metric-value">${s.onHold}<small>건</small></div><div class="metric-note">입고·고객 확인이 필요한 주문</div></button><button class="metric" data-view="claims"><div class="metric-label"><span>처리할 클레임</span><span>↺</span></div><div class="metric-value">${s.activeClaims}<small>건</small></div><div class="metric-note">취소·반품·교환 요청</div></button></div>`;}
function currentParams(){const p={...state.filters,page:state.page,limit:state.limit};if(state.view==='claims')p.claim='active';if(state.view==='memos')p.memo='true';return p;}
function queryString(extra={}){return new URLSearchParams(Object.fromEntries(Object.entries({...currentParams(),...extra}).filter(([,v])=>v!==''&&v!==undefined))).toString();}
async function refresh(keepFocus=false){const sequence=++refreshSequence;const [stats,data]=await Promise.all([api('/api/stats'),api('/api/orders?'+queryString())]);if(sequence!==refreshSequence)return;state.stats=stats;state.data=data;$('#navTotal').textContent=stats.total;$('#navClaims').textContent=stats.activeClaims;$('#crumb').textContent=titles[state.view];if(!keepFocus)render();else renderTable();}
function go(view){flushPendingDraft();$('#dialog').close();onNavigate?.(view);if(settingsOnly&&!['connections','settings'].includes(view))return;if(!settingsOnly&&['connections','settings'].includes(view))return;state.view=view;state.filters={};state.page=1;state.selected.clear();$('#nav').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));run(()=>refresh());}
function demoBanner(){return state.stats.demo?`<div class="banner"><span>예제 주문 ${state.stats.demo}건이 포함되어 있습니다. 실제 주문과 구분해서 확인해주세요.</span><button class="btn small" data-action="clearDemo">예제만 비우기</button></div>`:'';}
function render(){
  const main=$('#main');
  if(['orders','claims','memos'].includes(state.view)){
    main.innerHTML=(state.view==='orders'?`<div class="commerce-order-actions"><button class="btn primary" data-integration-action="collectDialog">↻ 주문 수집</button><details><summary class="btn">가져오기·도구</summary><div class="actions-inline"><button class="btn" data-action="create">주문 추가</button><button class="btn" data-action="import">주문 파일</button><button class="btn" data-action="trackingImport">송장 파일</button><button class="btn" data-action="export">엑셀 내보내기</button></div></details></div>`:'')+demoBanner()+`<section class="panel"><div class="tabs">${['전체',...state.boot.statuses].map(s=>`<button class="tab ${(state.filters.status||'전체')===s?'active':''}" data-tab="${s==='전체'?'':s}">${esc(s)}<small>${s==='전체'?state.stats.total:state.stats.counts[s]}</small></button>`).join('')}</div><div class="filterbar"><div class="search"><input id="search" aria-label="주문 검색" placeholder="주문번호, 상품명, 수령자, 송장번호 검색" value="${esc(state.filters.q||'')}"></div></div><details class="commerce-order-filters" ${Object.values(state.filters).some(Boolean)?'open':''}><summary>검색·상세 필터${Object.values(state.filters).some(Boolean)?' · 적용 중':''}</summary><div class="filterbar"><select data-filter="businessId" aria-label="사업자 필터"><option value="">전체 사업자</option>${(state.boot.businesses||[]).map(b=>`<option value="${esc(b.id)}" ${state.filters.businessId===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select><select data-filter="channel" aria-label="판매처 필터">${selectOptions([...new Set([...state.boot.channels,...state.boot.accounts.map(a=>a.channel)])],state.filters.channel,'판매처 전체')}</select><select data-filter="onHold" aria-label="보류 필터">${[['','보류 전체'],['false','보류 아님'],['true','보류됨']].map(([v,l])=>`<option value="${v}"${state.filters.onHold===v?' selected':''}>${l}</option>`).join('')}</select><select data-filter="workStatus" aria-label="작업 상태 필터">${selectOptions(state.boot.workStates,state.filters.workStatus,'작업상태 전체')}</select><div class="filter-date"><input type="date" data-filter="from" aria-label="주문일 시작" value="${esc(state.filters.from||'')}"><span>~</span><input type="date" data-filter="to" aria-label="주문일 종료" value="${esc(state.filters.to||'')}"></div><button class="btn small" data-action="resetFilter">초기화</button></div><div class="filter-help">쇼핑몰 연결에서 API 주문수집 또는 브라우저 화면 수집을 설정할 수 있습니다. 파일 가져오기도 함께 사용할 수 있습니다.</div></details><div id="selectionBar"></div><div id="ordersTable"></div></section>`;
    renderTable();
  }else if(state.view==='overview')renderOverview();
  else if(state.view==='reports')renderReports();
  else if(state.view==='settings'){renderSettings();renderBusinessSettings();}
  else if(['connections','forwarding'].includes(state.view))run(()=>window.DobiIntegrations.render(state.view));
}
function renderTable(){
  if(!$('#ordersTable'))return;const d=state.data;
  $('#selectionBar').innerHTML=state.selected.size?`<div class="selectionbar"><span class="selectioncount">${state.selected.size?'선택 '+state.selected.size+'건':'주문을 선택해 일괄 처리하세요'}</span><button class="btn small" data-action="bulkStatus" ${state.selected.size?'':'disabled'}>상태 변경</button><button class="btn small" data-action="hold" ${state.selected.size?'':'disabled'}>보류</button><button class="btn small" data-action="releaseHold" ${state.selected.size?'':'disabled'}>보류 해제</button><button class="btn small" data-action="tracking" ${state.selected.size?'':'disabled'}>송장 입력</button><button class="btn small" data-action="trackingImport">송장 파일</button><button class="btn small" data-integration-action="forwardCreate" ${state.selected.size?'':'disabled'}>배송대행 초안</button><button class="btn small" data-action="export">엑셀 내보내기</button><button class="btn small" data-action="print" ${state.selected.size?'':'disabled'}>인쇄</button></div>`:'';
  const rows=d.orders.map(o=>`<tr data-order-row="${o.id}" tabindex="0" class="${state.selected.has(o.id)?'selected':''}"><td class="check-cell"><input type="checkbox" data-select="${o.id}" aria-label="${esc(o.orderNo)} 선택" ${state.selected.has(o.id)?'checked':''}></td><td><button class="order-link" data-order="${o.id}">${esc(o.orderNo)}</button><span class="secondary">${esc(o.orderedAt)}</span></td><td><span class="channel-tag" data-channel="${esc(o.channel)}">${esc(o.channel)}</span><span class="secondary">${esc(o.account)}</span></td><td>${tag(o)}<span class="secondary">${esc(o.workStatus)}</span></td><td class="product-text"><strong>${esc(o.product)}</strong><span class="secondary">${esc(o.option||'옵션 없음')}${o.sku?' · '+esc(o.sku):''}</span></td><td class="number">${o.quantity}</td><td>${esc(o.recipient||'미입력')}<span class="secondary">${esc(o.phone)}</span></td><td class="number">${money(o.amount)}</td><td>${o.tracking?esc(o.tracking):'<span class="secondary">송장 미입력</span>'}<span class="secondary">${esc(o.carrier)}</span></td><td>${o.claimType!=='없음'?'<span class="pill claim">'+esc(o.claimType)+'</span>':o.workMemo?'<span class="pill">메모 있음</span>':'<span class="secondary">—</span>'}</td><td><button class="btn small" data-order="${o.id}">상세</button></td></tr>`).join('');
  $('#ordersTable').innerHTML=d.total?`<div class="table-wrap"><table><thead><tr><th class="check-cell"><input id="selectAll" type="checkbox" aria-label="현재 페이지 전체 선택" ${d.orders.length&&d.orders.every(o=>state.selected.has(o.id))?'checked':''}></th><th>주문번호 · 주문일</th><th>판매처 · 계정</th><th>주문상태</th><th>상품 · 옵션</th><th class="number">수량</th><th>수령자</th><th class="number">결제금액</th><th>배송 정보</th><th>CS · 클레임</th><th></th></tr></thead><tbody>${rows}</tbody></table></div><div class="pagination"><span class="summary">총 ${d.total.toLocaleString()}품목 · ${d.quantity.toLocaleString()}개 · ${money(d.amount)}</span><select id="pageSize" aria-label="페이지당 주문 수">${[25,50,100].map(n=>`<option ${state.limit===n?'selected':''}>${n}</option>`).join('')}</select><button class="btn small" data-action="prev" ${state.page>1?'':'disabled'}>이전</button><span>${state.page} / ${Math.max(1,Math.ceil(d.total/state.limit))}</span><button class="btn small" data-action="next" ${state.page*state.limit<d.total?'':'disabled'}>다음</button></div>`:`<div class="empty"><span class="empty-icon">▤</span><h3>${state.stats.total?'조건에 맞는 주문이 없습니다':'첫 주문을 가져와 보세요'}</h3><p>${state.stats.total?'검색어와 필터를 바꾸면 다른 주문을 확인할 수 있습니다.':'판매처에서 내려받은 주문 파일을 가져오거나 직접 추가하세요.<br>'}</p>${state.stats.total?'<button class="btn" data-action="resetFilter">필터 초기화</button>':'<button class="btn primary" data-action="import">주문 가져오기</button>'}</div>`;
}
function renderOverview(){const s=state.stats;$('#main').innerHTML=pageHead('오늘의 주문 작업실','지금 처리해야 할 주문을 먼저 확인하세요.',`<button class="btn primary" data-action="import">↥ 주문 가져오기</button>`)+metrics()+demoBanner()+`<div class="grid-two"><section class="panel content-panel"><p class="eyebrow">ORDER FLOW</p><h2>준비에서 구매확정까지</h2>${state.boot.statuses.map(status=>`<div class="bar-row"><span>${status}</span><div class="bar-track"><div class="bar-fill" style="width:${s.total?s.counts[status]/s.total*100:0}%"></div></div><button class="btn small" data-filter-status="${status}">${s.counts[status]}건 보기</button></div>`).join('')}</section><section class="panel content-panel"><p class="eyebrow">NEXT ACTION</p><h2>다음에 할 일</h2><div class="mini-grid"><div class="mini-stat"><span class="help">송장 입력 대기</span><b>${s.missingTracking}<small class="help"> 건</small></b></div><div class="mini-stat"><span class="help">보류 확인</span><b>${s.onHold}<small class="help"> 건</small></b></div><div class="mini-stat"><span class="help">클레임 처리</span><b>${s.activeClaims}<small class="help"> 건</small></b></div></div><p class="help">주문 상태와 보류·작업 상태는 따로 관리됩니다. 발송 전에는 보류 여부와 송장 정보를 확인해주세요.</p><button class="btn" data-view="orders">주문 목록 열기 →</button></section><section class="panel content-panel"><h3>최근 작업 이력</h3><div id="recentHistory" class="help">불러오는 중…</div></section><section class="panel content-panel"><h3>내 데이터 관리</h3><p class="help">주문은 선택한 회사·프로젝트의 전용 저장소에 보관됩니다. 중요한 작업 전에는 백업 파일을 보관해주세요.</p><div class="actions-inline"><a class="btn" href="/api/backup">전체 데이터 백업</a><a class="btn" href="/api/template">주문 엑셀 양식</a></div></section></div>`;run(async()=>{const h=await api('/api/history');if($('#recentHistory'))$('#recentHistory').innerHTML=h.length?h.slice(0,6).map(x=>`<div class="history-row">${esc(x.kind)} · ${esc(x.message)}<small>${new Date(x.created_at).toLocaleString('ko-KR')}</small></div>`).join(''):'아직 기록된 작업이 없습니다.';});}
function renderReports(){const s=state.stats,channels=Object.entries(s.channels),max=Math.max(1,...channels.map(([,v])=>v.amount));$('#main').innerHTML=pageHead('주문 통계','등록된 주문 데이터를 기준으로 판매처별·일별 현황을 확인합니다.',`<button class="btn" data-action="export">주문 엑셀 내보내기</button>`)+demoBanner()+`<div class="grid-two"><section class="panel content-panel"><p class="eyebrow">ORDER AMOUNT</p><h3>등록 주문금액</h3><div class="report-total">${money(s.amount)}</div><p class="help">취소·예제 주문이 포함된 전체 등록 금액입니다. 실제 매출·정산 입금액과 다를 수 있습니다.</p><div class="daily-row"><span>파일에 입력된 예상 정산액 합계</span><b>${money(s.expectedAmount)}</b></div></section><section class="panel content-panel"><p class="eyebrow">BY CHANNEL</p><h3>판매처별 주문금액</h3>${channels.length?channels.map(([c,v])=>`<div class="bar-row"><span>${esc(c)}<small class="secondary">${v.count}품목</small></span><div class="bar-track"><div class="bar-fill" style="width:${v.amount/max*100}%"></div></div><span class="value">${money(v.amount)}</span></div>`).join(''):'<p class="help">주문을 등록하면 통계가 표시됩니다.</p>'}</section><section class="panel content-panel"><h3>주문일별 현황</h3>${Object.entries(s.daily).sort(([a],[b])=>b.localeCompare(a)).slice(0,31).map(([d,v])=>`<div class="daily-row"><span>${d}</span><span>${v.count}품목</span><b>${money(v.amount)}</b></div>`).join('')||'<p class="help">표시할 주문이 없습니다.</p>'}</section><section class="panel content-panel"><h3>통계의 기준</h3><div class="info-box">주문 수는 상품 품목 행 수입니다.<br>동일 주문번호의 여러 상품은 별도 품목으로 표시됩니다.<br>예상 정산액이 없는 경우 입력된 결제금액−수수료로 계산합니다.<br>판매처의 실제 정산 결과는 별도로 확인해주세요.</div></section></div>`;}
function renderSettings(){const b=state.boot;$('#main').innerHTML=pageHead('내 작업실 설정','내 이름으로 정리하고, 데이터와 판매처 구분을 관리하세요.')+`<div class="grid-two"><section class="panel content-panel"><details class="settings-group"><summary>고급 · 인쇄·호환 이름</summary><form id="settingsForm"><div class="form-grid"><label class="field">프로그램 이름<input name="title" maxlength="50" required value="${esc(b.settings.title)}"></label><label class="field">업체명<input name="company" maxlength="100" value="${esc(b.settings.company)}" placeholder="인쇄에 표시할 업체명"></label></div><div class="form-actions"><button class="btn primary">저장</button></div></form></details><div class="settings-group"><h3>백업과 복원</h3><p class="help">백업에는 주문·메모·작업 이력이 포함됩니다. 복원 전 현재 데이터도 자동으로 보관합니다.</p><div class="actions-inline"><a class="btn" href="/api/backup">전체 백업 다운로드</a><button class="btn" data-action="restore">백업 복원</button></div></div><details class="settings-group"><summary>도움말 · 예제 데이터</summary><p class="help">예제 18품목으로 주문 작업을 연습할 수 있습니다.</p><div class="actions-inline"><button class="btn" data-action="demo">예제 주문 생성</button><button class="btn danger" data-action="clearDemo">예제만 삭제</button></div></details></section><section class="panel content-panel"><div class="settings-group"><h3>판매처와 계정 구분</h3><p class="help">파일 주문을 구분하기 위한 계정 이름입니다. 판매처에 로그인하거나 연결하는 기능은 아닙니다.</p><div class="account-list">${b.accounts.map(a=>`<div class="account-row"><span class="channel-tag">${esc(a.channel)}</span><span>${esc(a.name)}</span><small>파일 가져오기</small></div>`).join('')||'<p class="help">주문을 가져오면 계정 구분이 자동으로 추가됩니다.</p>'}</div><form id="accountForm"><div class="form-grid"><label class="field">판매처<select name="channel">${selectOptions(b.channels,'스마트스토어')}</select></label><label class="field">사업자<select name="businessId"><option value="">사업자 선택</option>${(state.boot.businesses||[]).map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('')}</select></label><label class="field">계정 이름<input name="name" required maxlength="200" placeholder="예: 1사업자 · 스토어 A"></label></div><div class="form-actions"><button class="btn">계정 구분 추가</button></div></form></div><div class="info-box"><b>자동 수집을 연결하려면</b><br>판매처별 공식 API 인증과 주문·송장 매핑을 설정해야 합니다. 쇼핑몰·배송대행 연결 메뉴에서 쿠팡·스마트스토어·카페24 공식 API와 사용자 정의 API, 브라우저 도우미를 설정할 수 있습니다. 샵마인의 저장된 비밀번호나 세션은 추출하지 않습니다.</div></section></div>`;}
function openDialog(title,html,{wide=false,kicker='ORDER WORKSPACE'}={}){const d=$('#dialog');d.classList.toggle('wide',wide);$('#dialogTitle').textContent=title;$('#dialogKicker').textContent=kicker;$('#dialogBody').innerHTML=html;const inspector=html.includes('id="orderForm"');if(d.open)d.close();d.classList.toggle('order-inspector',inspector);if(inspector)d.show();else d.showModal();}
function field(name,label,value='',type='text',wide=false){return `<label class="field ${wide?'wide':''}">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${['orderNo','product'].includes(name)?'required':''} ${type==='number'?'min="0" step="1"':''}></label>`;}
async function orderDialog(id){const detail=id?await api('/api/orders/'+id):null,o=detail?.order||{orderedAt:new Date().toLocaleDateString('sv-SE'),channel:'스마트스토어',account:'기본 계정',quantity:1,status:'신규',workStatus:'미지정',claimType:'없음',unitPrice:0,shippingFee:0,fee:0};openDialog(id?'주문 상세 · '+o.orderNo:'새 주문 등록',`${id?`<div class="detail-summary"><div>${tag(o)}</div><span>품목번호 ${esc(o.lineId)} · 마지막 수정 ${new Date(o.updatedAt).toLocaleString('ko-KR')}</span></div>`:''}<form id="orderForm" data-id="${id||''}" data-version="${o.version||''}"><div class="form-grid"><div class="form-section-title">01 · 주문과 상품</div>${field('orderNo','주문번호 *',o.orderNo)}${field('lineId','품목번호 / 상품주문번호',o.lineId)}<label class="field">판매처<select name="channel">${selectOptions([...new Set([...state.boot.channels,o.channel])],o.channel)}</select></label>${field('account','계정 이름',o.account)}${field('orderedAt','주문일',o.orderedAt,'date')}${field('sku','상품코드',o.sku)}${field('product','상품명 *',o.product,'text',true)}${field('option','옵션',o.option,'text',true)}<div class="triple">${field('quantity','수량',o.quantity,'number')}${field('unitPrice','단가 (원)',o.unitPrice,'number')}${field('amount','결제금액 (원)',o.amount,'number')}</div><div class="triple">${field('shippingFee','배송비 (원)',o.shippingFee,'number')}${field('fee','수수료 (원)',o.fee,'number')}${field('expectedAmount','예상정산액 (원)',o.expectedAmount,'number')}</div><div class="form-section-title">02 · 받는 사람과 배송</div>${field('buyer','구매자',o.buyer)}${field('recipient','수령자',o.recipient)}${field('phone','연락처',o.phone)}${field('postcode','우편번호',o.postcode)}${field('address','주소',o.address,'text',true)}${field('deliveryMemo','배송메모',o.deliveryMemo,'text',true)}<label class="field">택배사<select name="carrier">${selectOptions([...new Set([...state.boot.carriers,...(o.carrier?[o.carrier]:[])])],o.carrier,'미지정')}</select></label>${field('tracking','송장번호',o.tracking)}<div class="form-section-title">03 · 상태와 메모</div><label class="field">주문상태<select name="status">${selectOptions(state.boot.statuses,o.status)}</select></label><label class="field">작업상태<select name="workStatus">${selectOptions(state.boot.workStates,o.workStatus)}</select></label><label class="check-label wide"><input type="checkbox" name="onHold" ${o.onHold?'checked':''}> 이 주문 발송 보류</label>${field('holdReason','보류 사유',o.holdReason)}${field('holdUntil','보류 확인 예정일',o.holdUntil,'date')}<label class="field wide">CS · 작업 메모<textarea name="workMemo">${esc(o.workMemo)}</textarea></label><label class="field">클레임 상태<select name="claimType">${selectOptions(state.boot.claims,o.claimType)}</select></label><label class="field wide">클레임 메모<textarea name="claimNote">${esc(o.claimNote)}</textarea></label></div><div id="formError" class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="btn" data-action="close">닫기</button><button class="btn primary">${id?'변경 저장':'주문 등록'}</button></div></form>${detail?`<div class="inline-history"><h3>변경 이력</h3>${detail.history.map(h=>`<div class="history-row">${esc(h.kind)} · ${esc(h.message)}<small>${new Date(h.created_at).toLocaleString('ko-KR')}</small></div>`).join('')}</div>`:''}`,{wide:true});}
function bulkDialog(kind){if(!state.selected.size)throw Error('주문을 선택해주세요.');const count=state.selected.size;let html;
  if(kind==='hold')html=`<label class="field">보류 사유 *<input name="holdReason" required placeholder="예: 입고 대기, 고객 확인"></label>${field('holdUntil','확인 예정일','','date')}`;
  if(kind==='tracking')html=`<div class="info-box">선택한 ${count}품목에 같은 송장번호를 적용합니다. 주문별로 다른 송장을 넣으려면 ‘송장 파일’을 사용해주세요.</div><br><label class="field">택배사<select name="carrier">${selectOptions(state.boot.carriers,'CJ대한통운')}</select></label>${field('tracking','송장번호 *')}`;
  if(kind==='bulkStatus')html=`<div class="info-box">배송중으로 변경하려면 송장이 필요하고, 보류가 해제되어 있어야 합니다. 한 주문이라도 잘못된 경우 전체 변경을 취소합니다.</div><br><label class="field">주문상태<select name="status">${selectOptions(state.boot.statuses,'','변경하지 않음')}</select></label><br><label class="field">작업상태<select name="workStatus">${selectOptions(state.boot.workStates,'','변경하지 않음')}</select></label>`;
  openDialog(kind==='hold'?'선택 주문 보류':kind==='tracking'?'선택 주문 송장 입력':'선택 주문 상태 변경',`<p class="help">${count}품목 선택됨</p><form id="bulkForm" data-kind="${kind}"><div class="form-grid">${html}</div><div class="form-error" id="formError" role="alert"></div><div class="form-actions"><button type="button" class="btn" data-action="close">닫기</button><button class="btn primary">적용</button></div></form>`);}
function startImport(mode='orders'){importState={mode,mapping:{},defaults:{channel:'',account:'',carrier:'CJ대한통운'},parsed:null};openDialog(mode==='orders'?'주문 파일 가져오기':'송장 파일 가져오기',`<div class="step-progress"><span class="done"></span><span></span><span></span></div><div class="step-label">1 / 3 · 파일 선택</div><div class="info-box">${mode==='orders'?'샵마인 또는 판매처에서 내려받은 주문 파일을 선택하세요. 다음 단계에서 열을 연결하고 저장할 내용을 확인합니다.':'주문번호·택배사·송장번호가 있는 파일을 선택하세요. 여러 판매처의 주문번호가 겹치면 판매처·계정도 연결해주세요.'}<br>첫 시트만 사용하며 XLSX·CSV·TSV, 최대 10MB·10,000행을 지원합니다.</div><div class="upload-area"><p>가져올 파일을 선택해주세요.</p><input type="file" id="importFile" accept=".xlsx,.csv,.tsv" aria-label="가져올 주문 파일"></div><p class="help">주문번호·품목번호·송장번호는 엑셀에서 ‘텍스트’로 저장해주세요.</p><div class="form-error" id="importError" role="alert"></div><div class="form-actions">${mode==='orders'?'<button class="btn" data-action="sampleImport">예제 CSV로 연습</button>':''}<a class="btn" href="/api/template?mode=${mode}">엑셀 양식 받기</a><button class="btn primary" data-action="parseImport">열 연결하기 →</button></div>`,{wide:true,kicker:'IMPORT ORDERS'});}
async function parseImport(){const f=$('#importFile')?.files?.[0];if(!f)throw Error('파일을 선택해주세요.');if(f.size>10*1024*1024)throw Error('파일은 10MB 이하로 올려주세요.');const button=$('[data-action="parseImport"]');button.disabled=true;try{const bytes=new Uint8Array(await f.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));importState.parsed=await api('/api/import/parse',{name:f.name,content:btoa(binary),mode:importState.mode});importState.name=f.name;importState.mapping=importState.parsed.mapping;renderMapping();}catch(e){button.disabled=false;$('#importError').textContent=e.message;}}
function renderMapping(){const i=importState,fields=i.mode==='tracking'?['orderNo','lineId','channel','account','carrier','tracking']:Object.keys(state.boot.fields);openDialog(i.mode==='orders'?'주문 파일 가져오기':'송장 파일 가져오기',`<div class="step-progress"><span class="done"></span><span class="done"></span><span></span></div><div class="step-label">2 / 3 · 열 연결</div><p class="help"><b>${esc(i.name)}</b> · ${i.parsed.total.toLocaleString()}행. 자동으로 연결한 항목을 확인해주세요.</p><div class="mapping-grid">${fields.map(f=>`<label class="field ${['orderNo','product','tracking'].includes(f)?'required':''}">${esc(state.boot.fields[f])}${f==='orderNo'||i.mode==='orders'&&f==='product'||i.mode==='tracking'&&f==='tracking'?' *':''}<select data-map="${f}">${selectOptions(i.parsed.headers,i.mapping[f],'연결하지 않음')}</select></label>`).join('')}</div><h3>파일에 판매처·계정이 없는 경우</h3><div class="form-grid"><label class="field">기본 판매처<select data-default="channel">${selectOptions(state.boot.channels,i.defaults.channel,'지정하지 않음')}</select></label><label class="field">기본 계정 이름<input data-default="account" value="${esc(i.defaults.account)}" placeholder="예: 1사업자 · 스토어 A"></label>${i.mode==='tracking'?`<label class="field">기본 택배사<select data-default="carrier">${selectOptions(state.boot.carriers,i.defaults.carrier)}</select></label>`:''}</div><div class="form-error" id="importError" role="alert"></div><div class="form-actions"><button class="btn" data-action="restartImport">다른 파일</button><button class="btn primary" data-action="previewImport">미리보기 →</button></div>`,{wide:true});}
async function previewImport(){const i=importState;$$('[data-map]').forEach(e=>i.mapping[e.dataset.map]=e.value);$$('[data-default]').forEach(e=>i.defaults[e.dataset.default]=e.value);const preview=await api('/api/import/preview',{id:i.parsed.id,mapping:i.mapping,defaults:i.defaults});i.preview=preview;openDialog('가져오기 미리보기',`<div class="step-progress"><span class="done"></span><span class="done"></span><span class="done"></span></div><div class="step-label">3 / 3 · 저장 전 확인</div><div class="${preview.errorCount?'error-list':'success-info'}">총 ${preview.total}행 · 정상 ${preview.valid}행 · 오류 ${preview.errorCount}행${i.mode==='orders'?'<br>기존 주문과 중복된 품목은 건너뛰고, 메모·송장·상태를 유지합니다.':''}</div>${preview.warnings.map(w=>`<p class="help">${esc(w)}</p>`).join('')}<h3 style="margin-top:var(--dobi-value-19)">첫 ${preview.rows.length}행</h3><div class="preview-table"><table><thead><tr><th>주문번호</th><th>판매처 · 계정</th><th>${i.mode==='orders'?'상품':'택배사'}</th><th>${i.mode==='orders'?'수량':'송장번호'}</th><th>${i.mode==='orders'?'결제금액':''}</th></tr></thead><tbody>${preview.rows.map(o=>`<tr><td>${esc(o.orderNo)}</td><td>${esc(o.channel)} / ${esc(o.account)}</td><td>${esc(i.mode==='orders'?o.product:o.carrier)}</td><td>${esc(i.mode==='orders'?o.quantity:o.tracking)}</td><td>${i.mode==='orders'?money(o.amount):''}</td></tr>`).join('')}</tbody></table></div>${preview.errors.length?`<div class="error-list">${preview.errors.map(e=>`${e.row}행: ${esc(e.message)}`).join('<br>')}</div>`:''}<div class="form-error" id="importError" role="alert"></div><div class="form-actions"><button class="btn" data-action="mappingBack">← 열 연결 수정</button><button class="btn primary" data-action="commitImport" ${preview.errorCount?'disabled':''}>${i.mode==='orders'?'주문 가져오기':'송장 등록하기'}</button></div>`,{wide:true});}
async function commitImport(){const i=importState,b=$('[data-action="commitImport"]');b.disabled=true;try{const r=await api('/api/import/commit',{id:i.parsed.id,mapping:i.mapping,defaults:i.defaults});$('#dialog').close();state.selected.clear();await reloadBoot();await refresh();toast(i.mode==='orders'?`${r.inserted}품목 등록 · 중복 ${r.duplicates}품목 건너뜀`:`${r.updated}품목의 송장을 등록했습니다.`);}catch(e){$('#importError').textContent=e.message;b.disabled=false;}}
async function exportDialog(){openDialog('주문 내보내기',`<p class="help">${state.selected.size?'선택한 '+state.selected.size+'품목':'현재 검색·필터에 맞는 전체 주문'}을 내보냅니다.</p><div class="actions-inline"><button class="btn primary" data-action="downloadXlsx">주문 엑셀 다운로드</button><button class="btn" data-action="downloadCsv">주문 CSV 다운로드</button><button class="btn" data-action="downloadTracking">송장 엑셀 다운로드</button></div><p class="help">송장 엑셀은 로컬 입력 결과를 담은 파일입니다. 판매처에 자동 전송하지 않습니다.</p>`);}
function downloadExport(format,mode='orders'){const p={format,mode};if(state.selected.size)p.ids=[...state.selected].join(',');location.assign('/api/export?'+queryString(p));$('#dialog').close();}
async function printOrders(){const result=await api('/api/orders?'+queryString({all:'true'}));const orders=result.orders.filter(o=>state.selected.has(o.id));if(!orders.length)throw Error('현재 필터에 맞는 주문을 선택해주세요.');let print=$('.print-only');if(!print){print=document.createElement('div');print.className='print-only';document.body.append(print);}print.innerHTML=orders.map(o=>`<section class="print-order"><h2>${esc(state.boot.settings.company||state.boot.settings.title)} · 주문서</h2><p>판매처: ${esc(o.channel)} / ${esc(o.account)} · 주문번호: ${esc(o.orderNo)}</p><p>수령자: ${esc(o.recipient)} · 연락처: ${esc(o.phone)}</p><p>배송지: (${esc(o.postcode)}) ${esc(o.address)}</p><table><tr><th>상품</th><th>옵션</th><th>수량</th></tr><tr><td>${esc(o.product)}</td><td>${esc(o.option)}</td><td>${o.quantity}</td></tr></table><p>배송메모: ${esc(o.deliveryMemo)}</p><p>택배사: ${esc(o.carrier)} · 송장: ${esc(o.tracking)}</p>${o.demo?'<b>예제 데이터 — 실제 배송 불가</b>':''}</section>`).join('');window.print();}
function restoreDialog(){openDialog('백업 복원',`<div class="info-box">현재 주문·메모·이력을 백업 파일의 내용으로 바꿉니다. 복원 전에 현재 데이터 전체가 프로그램의 data/backups 폴더에 자동 보관됩니다.</div><div class="upload-area"><input type="file" id="restoreFile" accept=".json" aria-label="복원할 백업 파일"></div><label class="check-label"><input type="checkbox" id="confirmRestore"> 현재 데이터를 백업 내용으로 교체하는 것을 확인했습니다.</label><div id="restoreError" class="form-error" role="alert"></div><div class="form-actions"><button class="btn" data-action="close">취소</button><button class="btn primary" data-action="commitRestore">복원하기</button></div>`);}
async function reloadBoot(){state.boot=await api('/api/bootstrap');state.boot.businesses=await api('/api/businesses');document.title=state.boot.settings.title;const brand=document.querySelector('.brand>span:last-child');brand.replaceChildren(document.createTextNode(state.boot.settings.title));const caption=document.createElement('small');caption.textContent=state.boot.settings.company||'나의 주문 작업실';brand.append(caption);}
document.addEventListener('click',e=>{
  const button=e.target.closest('button,[data-action]');if(!button)return;
  if(button.dataset.view){go(button.dataset.view);return;}
  if(button.dataset.filterStatus!==undefined){go('orders');state.filters.status=button.dataset.filterStatus;state.page=1;run(()=>refresh());return;}
  if(button.hasAttribute('data-filter-hold')){go('orders');state.filters.onHold='true';run(()=>refresh());return;}
  if(button.dataset.tab!==undefined){state.filters.status=button.dataset.tab;state.page=1;state.selected.clear();run(()=>refresh());return;}
  if(button.dataset.order){run(()=>orderDialog(button.dataset.order));return;}
  const action=button.dataset.action;if(!action)return;
  run(async()=>{
    if(action==='close')$('#dialog').close();
    else if(action==='create')await orderDialog();
    else if(action==='import')startImport();
    else if(action==='trackingImport')startImport('tracking');
    else if(action==='parseImport')await parseImport();
    else if(action==='sampleImport'){importState.parsed=await api('/api/import/sample',{});importState.name='예제_주문.csv';importState.mapping=importState.parsed.mapping;renderMapping();}
    else if(action==='previewImport'){try{await previewImport();}catch(e){$('#importError').textContent=e.message;}}
    else if(action==='commitImport')await commitImport();
    else if(action==='mappingBack')renderMapping();
    else if(action==='restartImport')startImport(importState.mode);
    else if(['hold','tracking','bulkStatus'].includes(action))bulkDialog(action);
    else if(action==='releaseHold'){await api('/api/bulk',{ids:[...state.selected],patch:{onHold:false,holdReason:'',holdUntil:''}});await refresh();toast('선택 주문의 보류를 해제했습니다.');}
    else if(action==='resetFilter'){state.filters={};state.selected.clear();state.page=1;await refresh();}
    else if(action==='prev'||action==='next'){state.page+=action==='prev'?-1:1;state.selected.clear();await refresh();}
    else if(action==='export')await exportDialog();
    else if(action==='downloadXlsx')downloadExport('xlsx');
    else if(action==='downloadCsv')downloadExport('csv');
    else if(action==='downloadTracking')downloadExport('xlsx','tracking');
    else if(action==='print')await printOrders();
    else if(action==='demo'){await api('/api/demo',{});await reloadBoot();await refresh();toast('예제 주문 18품목을 추가했습니다.');}
    else if(action==='clearDemo'){if(!state.stats.demo)throw Error('삭제할 예제 데이터가 없습니다.');openDialog('예제 데이터만 삭제',`<p>‘예제’로 표시된 ${state.stats.demo}품목과 해당 이력을 삭제합니다. 실제 가져온 주문은 유지합니다.</p><div class="form-actions"><button class="btn" data-action="close">취소</button><button class="btn danger" data-action="confirmClearDemo">예제만 삭제</button></div>`);}
    else if(action==='confirmClearDemo'){await api('/api/demo',undefined,'DELETE');$('#dialog').close();state.selected.clear();await reloadBoot();await refresh();toast('예제 데이터를 삭제했습니다.');}
    else if(action==='restore')restoreDialog();
    else if(action==='commitRestore'){try{const f=$('#restoreFile').files[0];if(!f)throw Error('백업 파일을 선택해주세요.');if(!$('#confirmRestore').checked)throw Error('교체 확인 항목을 선택해주세요.');if(f.size>14*1024*1024)throw Error('백업 파일은 14MB 이하로 올려주세요.');const r=await api('/api/restore',JSON.parse(await f.text()));$('#dialog').close();state.selected.clear();await reloadBoot();await refresh();toast(`${r.restored}품목을 복원했습니다. 기존 데이터도 백업됐습니다.`);}catch(e){$('#restoreError').textContent=e.message;}}
  });
});
document.addEventListener('change',e=>{
  if(e.target.dataset.filter){state.filters[e.target.dataset.filter]=e.target.value;state.page=1;state.selected.clear();run(()=>refresh());}
  if(e.target.dataset.select){e.target.checked?state.selected.add(e.target.dataset.select):state.selected.delete(e.target.dataset.select);renderTable();}
  if(e.target.id==='selectAll'){for(const o of state.data.orders)e.target.checked?state.selected.add(o.id):state.selected.delete(o.id);renderTable();}
  if(e.target.id==='pageSize'){state.limit=Number(e.target.value);state.page=1;state.selected.clear();run(()=>refresh());}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){clearTimeout(searchTimer);state.filters.q=e.target.value;state.page=1;state.selected.clear();searchTimer=setTimeout(()=>run(()=>refresh(true)),230);}});
document.addEventListener('submit',async e=>{
  if(e.target.matches('[data-integrations]'))return;
  e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form)),button=form.querySelector('button:not([type=button])');if(button)button.disabled=true;
  try{
    if(form.id==='orderForm'){
      values.onHold=form.elements.onHold.checked;
      for(const f of ['quantity','unitPrice','shippingFee','fee','amount','expectedAmount'])values[f]=values[f]===''?undefined:Number(values[f]);
      if(form.dataset.id)await api('/api/orders/'+form.dataset.id,{patch:values,expectedVersion:Number(form.dataset.version)},'PATCH');else await api('/api/orders',values);
      $('#dialog').close();await reloadBoot();await refresh();toast('주문을 저장했습니다.');
    }else if(form.id==='bulkForm'){
      const kind=form.dataset.kind;let patch=values;
      if(kind==='hold')patch={...values,onHold:true};
      if(kind==='bulkStatus'){patch=Object.fromEntries(Object.entries(values).filter(([,v])=>v!==''));if(!Object.keys(patch).length)throw Error('변경할 상태를 선택해주세요.');}
      await api('/api/bulk',{ids:[...state.selected],patch});$('#dialog').close();await refresh();toast('선택 주문을 저장했습니다.');
    }else if(form.id==='accountForm'){await api('/api/accounts',values);await reloadBoot();renderSettings();toast('계정 구분을 추가했습니다.');}
    else if(form.id==='settingsForm'){await api('/api/settings',values);await reloadBoot();toast('작업실 설정을 저장했습니다.');}
  }catch(error){const target=form.querySelector('#formError');if(target)target.textContent=error.message;else toast(error.message,true);}finally{if(button&&button.isConnected)button.disabled=false;}
});
$('#closeDialog').onclick=()=>$('#dialog').close();$('#refreshBtn').onclick=()=>run(()=>refresh());
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#dialog').open)state.selected.clear();});
$('#today').textContent=new Date().toLocaleDateString('ko-KR',{year:'numeric',month:'long',day:'numeric',weekday:'short'});
window.DobiUI={api,toast,openDialog,run,esc,money,refresh,selected:()=>[...state.selected],go,reloadBoot,businesses:()=>state.boot.businesses||[],businessFor:(channel,account)=>state.boot.accountBusinesses?.find(a=>a.channel===channel&&a.account===account)?.businessId||''};


(() => {
  'use strict';
  const state={view:'connections',providers:[],catalogCounts:{},connections:[],drafts:[],runs:[],query:'',kind:'all',readiness:'all',limit:30,sequence:0,edit:null,pendingOrders:[],pair:null};
  const ui=()=>window.DobiUI;
  const $=selector=>document.querySelector(selector);
  const esc=v=>ui().esc(v);
  const arr=(data,key)=>Array.isArray(data)?data:Array.isArray(data?.[key])?data[key]:[];
  const provider=id=>state.providers.find(p=>p.id===id);
  const connection=id=>state.connections.find(c=>c.id===id);
  const action=(name,label,attrs='',classes='')=>`<button type="button" class="btn ${classes}" data-integration-action="${name}" ${attrs}>${label}</button>`;
  const today=()=>new Date(Date.now()+9*3600000).toISOString().slice(0,10);
  const weekAgo=()=>new Date(Date.now()+9*3600000-6*86400000).toISOString().slice(0,10);
  const time=v=>v&&Number.isFinite(Date.parse(v))?new Date(v).toLocaleString('ko-KR'):'—';
  const kindLabel=kind=>kind==='forwarder'?'배송대행지':'쇼핑몰';
  const modeLabel=mode=>({official:'공식 API',session:'지마켓·옥션 세션 API',api:'직접 설정한 API',browser:'브라우저 도우미'}[mode]||mode||'미설정');
  const safeUrl=url=>{try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}};
  function link(url,label,classes='btn small'){const href=safeUrl(url);return href?`<a class="${classes}" href="${esc(href)}" target="_blank" rel="noopener noreferrer">${label}</a>`:'';}
  function head(title,description,actions=''){return `<div class="page-head"><div><p class="eyebrow">CONNECTED WORKSPACE</p><h2>${esc(title)}</h2><p class="subtitle">${esc(description)}</p></div><div class="head-actions">${actions}</div></div>`;}
  function close(){const d=$('#dialog');if(d?.open)d.close();}
  function formError(form,error){const box=form.querySelector('[data-integration-error]');if(box)box.textContent=error.message||String(error);else ui().toast(error.message||String(error),true);}
  function summary(s={}){return [['inserted','신규'],['updated','갱신'],['unchanged','동일'],['duplicates','중복'],['unmatched','미매칭']].filter(([k])=>s[k]!==undefined).map(([k,label])=>`${label} ${Number(s[k]||0)}건`).join(' · ')||s.message||'처리 결과를 확인했습니다.';}
  function badge(p){if(p.sessionApi)return '<span class="int-badge implemented">ESM 수집 구현</span>';return p.official?'<span class="int-badge implemented">공식 수집 구현</span>':p.browserUrl?'<span class="int-badge browser">웹 페이지 확인</span>':'<span class="int-badge pending">연결 규칙 필요</span>';}
  function capability(p){
    if(p.sessionApi)return '지마켓·옥션 정상 로그인 세션 · 기간별 주문 수집';
    if(p.official)return '공식 API 인증 · 주문 수집';
    if(p.kind==='forwarder')return p.browserUrl?'브라우저 신청서 입력 도우미 · API 규칙 필요':'배송신청 초안 · 송장 API 규칙 필요';
    return p.browserUrl?'브라우저 화면 가져오기 · API 규칙 필요':'주문수집 API 규칙 필요';
  }
  async function load(){
    const [catalog,connections,runs]=await Promise.all([ui().api('/api/integrations/catalog'),ui().api('/api/connections'),ui().api('/api/integration-runs')]);
    if(!Array.isArray(catalog?.providers))throw Error('연동 목록을 읽지 못했습니다.');
    state.providers=catalog.providers;state.catalogCounts=catalog.counts||{};state.connections=arr(connections,'connections');state.runs=arr(runs,'runs');
  }
  async function render(view='connections'){
    state.view=view;const sequence=++state.sequence,main=$('#main');if(!main)return;
    main.innerHTML='<div id="integrationsScreen" class="loading" aria-live="polite">연동 작업실을 불러오는 중…</div>';
    const holder=$('#integrationsScreen');
    try{
      await load();if(view==='forwarding')state.drafts=arr(await ui().api('/api/forwarding'),'drafts');
      if(sequence!==state.sequence||!holder.isConnected)return;
      holder.className='int-screen';holder.innerHTML=view==='forwarding'?forwardingHtml():connectionsHtml();
      if(view==='connections')renderCatalog();
    }catch(error){if(holder.isConnected){holder.className='int-screen';holder.innerHTML=`${head('연동 작업실','현재 목록을 확인하지 못했습니다.')}<div class="info-box" role="alert">${esc(error.message)}</div><p>${action('refresh','다시 확인')}</p>`;}}
  }
  function connectionsHtml(){
    return head('쇼핑몰 · 배송대행 연결','판매처 계정을 연결하고 주문 수집과 배송신청을 이어서 관리하세요.',action('pairDialog','브라우저 도우미')+action('collectDialog','주문 수집','', 'primary'))+
      `<section class="panel content-panel int-section"><div class="int-section-head"><div><h2>내 연결 계정</h2><p class="help">인증 정보는 Dovix의 암호화 저장소에 보관합니다.</p></div>${action('connectionAdd','＋ 계정 연결')}</div>${state.connections.length?`<div class="int-accounts">${state.connections.map(c=>accountHtml(c)).join('')}</div>`:'<div class="int-empty">아직 연결한 계정이 없습니다. 계정 연결 또는 제공업체 목록을 열어 추가해주세요.</div>'}</section>`+
      `<details class="panel int-section"><summary class="int-catalog-head">제공업체 목록·계정 추가</summary><div class="int-catalog-head"><h2>연결할 곳 찾기</h2><p class="help">목록에 포함된 대상과 현재 구현된 연결 기능을 구분해서 표시합니다.</p><div class="int-filter"><input id="integrationSearch" type="search" aria-label="쇼핑몰 · 배송대행지 검색" placeholder="쿠팡, 스마트스토어, 배송대행지 이름 검색" value="${esc(state.query)}"><select id="integrationKind" aria-label="연동 종류"><option value="all"${state.kind==='all'?' selected':''}>전체</option><option value="market"${state.kind==='market'?' selected':''}>쇼핑몰</option><option value="forwarder"${state.kind==='forwarder'?' selected':''}>배송대행지</option></select><select id="integrationReadiness" aria-label="연결 방식"><option value="all"${state.readiness==='all'?' selected':''}>모든 연결 방식</option><option value="official"${state.readiness==='official'?' selected':''}>공식 수집 구현</option><option value="session"${state.readiness==='session'?' selected':''}>지마켓·옥션 API</option><option value="browser"${state.readiness==='browser'?' selected':''}>브라우저 연결</option><option value="pending"${state.readiness==='pending'?' selected':''}>연결 규칙 필요</option></select></div></div><p id="integrationCount" class="int-count" aria-live="polite"></p><div id="integrationCatalog" class="int-catalog"></div><div id="integrationMore" class="int-more"></div></details>`+runsHtml();
  }
  function accountHtml(c){
    const p=provider(c.providerId)||{},canRun=c.mode!=='browser'&&(c.mode!=='session'||c.hasCredentials),id=esc(c.id),stateLabel=c.busy?'작업 중':c.state||'인증 필요';
    return `<article class="int-account"><div class="int-account-main"><div class="int-account-title"><b>${esc(c.name)}</b><span class="channel-tag">${esc(c.mode==='session'?c.channel:p.name||c.channel)}</span><span class="int-state${c.lastError?' error':''}">${esc(stateLabel)}</span></div><p class="help">${kindLabel(c.kind)} · ${esc(modeLabel(c.mode))}${c.mode==='session'?' · 판매자 '+esc(c.sellerId):''}${c.hasCredentials?' · 인증 정보 저장됨':''}${c.lastRunAt?' · '+esc(time(c.lastRunAt)):''}</p>${c.lastError?`<p class="int-error">${esc(c.lastError)}</p>`:''}</div><div class="actions-inline">${action('connectionEdit','설정',`data-id="${id}"`,'small')}${c.mode==='session'?action('esmSessionDialog',c.hasCredentials?'세션 다시 연결':'브라우저로 연결',`data-id="${id}" ${c.busy?'disabled':''}`,'small'):''}${canRun?action('connectionTest','인증 확인',`data-id="${id}" ${c.busy?'disabled':''}`,'small'):link(p.browserUrl,'로그인 열기')}${c.kind==='market'&&canRun?action('collectDialog','주문 수집',`data-id="${id}" ${c.busy?'disabled':''}`,'small primary'):c.kind==='forwarder'&&c.mode==='api'?action('trackingDialog','송장 회수',`data-id="${id}" ${c.busy?'disabled':''}`,'small primary'):action('pairDialog','도우미 안내','','small')}</div></article>`;
  }
  function renderCatalog(){
    const container=$('#integrationCatalog');if(!container)return;
    const q=state.query.trim().toLocaleLowerCase(),filtered=state.providers.filter(p=>(state.kind==='all'||p.kind===state.kind)&&(!q||`${p.name} ${p.id}`.toLocaleLowerCase().includes(q))&&(state.readiness==='all'||state.readiness==='official'&&p.official||state.readiness==='session'&&p.sessionApi||state.readiness==='browser'&&!p.official&&p.browserUrl||state.readiness==='pending'&&!p.official&&!p.browserUrl));
    $('#integrationCount').textContent=`${filtered.length}곳${q?' 검색 결과':''} · 현재 ${Math.min(filtered.length,state.limit)}곳 표시`;
    container.innerHTML=filtered.length?filtered.slice(0,state.limit).map(p=>`<article class="int-provider"><div class="int-provider-top"><span>${kindLabel(p.kind)}</span>${badge(p)}</div><h3>${esc(p.name)}</h3><p class="help">${esc(capability(p))}<br>${p.sessionApi?'ESM에서 정상 로그인한 뒤 브라우저 세션을 연결해주세요.':p.official?'인증 후 실제 주문 조회를 확인해주세요.':'입력 양식과 API 수집 규칙은 확인이 필요합니다.'}</p><div class="actions-inline">${action('connectionAdd','연결 설정',`data-provider="${esc(p.id)}"`,'small')}${link(p.browserUrl,'페이지 열기')}</div></article>`).join(''):'<div class="int-empty">검색 조건에 맞는 대상이 없습니다.</div>';
    $('#integrationMore').innerHTML=filtered.length>state.limit?action('catalogMore','목록 더 보기'):'';
  }
  function runsHtml(){return `<section class="panel content-panel int-section"><h2>최근 연동 이력</h2>${state.runs.length?`<div class="table-wrap"><table><thead><tr><th>계정</th><th>작업</th><th>결과</th><th>내용</th><th>일시</th></tr></thead><tbody>${state.runs.slice(0,12).map(r=>`<tr><td>${esc(connection(r.connectionId)?.name||'계정')}</td><td>${esc(r.kind)}</td><td><span class="int-state${r.state==='실패'?' error':''}">${esc(r.state)}</span></td><td class="int-wrap">${esc(summary(r.summary))}</td><td>${esc(time(r.createdAt||r.created_at))}</td></tr>`).join('')}</tbody></table></div>`:'<p class="help">실행한 연동 작업이 없습니다.</p>'}</section>`;}
  function credentialFields(p,mode){
    const fields={coupang:[['vendorId','판매자 ID (Vendor ID)',false],['accessKey','Access Key',true],['secretKey','Secret Key',true]],smartstore:[['clientId','애플리케이션 ID',false],['clientSecret','애플리케이션 시크릿',true],['type','인증 유형',false],['accountId','판매자 ID (SELLER 유형만)',false]],cafe24:[['mallId','쇼핑몰 ID',false],['accessToken','OAuth Access Token',true],['shopNo','멀티쇼핑몰 번호 (기본 1)',false]]};
    if(mode==='session')return `<div class="info-box">ESM에서 정상 로그인한 세션으로 지마켓 또는 옥션 주문을 조회합니다. 계정별로 판매자 ID를 지정해주세요.</div><div class="form-grid int-top-gap"><label class="field">쇼핑몰<select name="sessionSite"><option value="gmarket"${state.edit?.site==='auction'?'':' selected'}>지마켓</option><option value="auction"${state.edit?.site==='auction'?' selected':''}>옥션</option></select></label><label class="field">ESM 판매자 ID<input name="sellerId" value="${esc(state.edit?.sellerId||'')}" required maxlength="100" autocomplete="off" placeholder="해당 쇼핑몰에 등록한 판매자 ID"></label></div><p class="help">저장 후 브라우저 도우미에서 연결합니다. 쿠키는 이 PC의 Windows 암호화 저장소에 보관합니다. 세션이 만료되면 ESM에서 다시 로그인하고 연결해주세요.</p>`;
    if(mode==='browser')return `<div class="info-box">사용하시는 브라우저에서 직접 로그인한 다음 도우미를 연결해주세요. 추가 인증은 해당 쇼핑몰 화면에서 진행합니다.</div><p class="help">로그인 정보를 이 화면에 입력할 필요가 없습니다. 도우미의 ‘현재 화면 수집’ 또는 ‘신청서 채우기’를 직접 눌러 실행합니다.</p>${link(p.browserUrl,'로그인 · 신청 페이지 열기','btn')}`;
    if(mode==='official')return `<div class="form-grid">${(fields[p.id]||[]).map(([key,label,secret])=>`<label class="field">${esc(label)}${key==='type'?'<select name="credential_type"><option value="">저장된 값 유지 / 기본 SELF</option><option value="SELF">SELF · 내 스토어</option><option value="SELLER">SELLER · 연결 판매자</option></select>':`<input name="credential_${key}" type="${secret?'password':'text'}" autocomplete="off" spellcheck="false" placeholder="${state.edit?.hasCredentials?'빈칸이면 저장된 값 유지':'직접 입력해주세요'}">`}</label>`).join('')}</div><p class="help">${p.id==='coupang'?'Wing에서 발급한 Open API 키와 판매자 ID를 입력해주세요. 현재 접속 IP에 API 사용 권한이 필요합니다.':p.id==='smartstore'?'내 스토어 애플리케이션은 SELF를 사용합니다. 주문 조회 권한과 API 접속 허용 IP를 확인해주세요.':'쇼핑몰 주문 읽기 권한이 있는 OAuth 토큰을 입력해주세요. 토큰이 만료되면 다시 발급받아 입력합니다.'}</p>`;
    return `<div class="info-box">대상 업체에서 확인한 API 주소와 응답 규칙을 입력해주세요. 예제 주소는 설명용이며 실제 연동 주소가 아닙니다.</div><div class="actions-inline int-editor-tools">${action('recipeExample','규칙 예제 불러오기',`data-kind="${esc(p.kind)}"`,'small')}</div><label class="field">API 연결 규칙 (JSON)<textarea name="recipe" class="int-code" rows="12" required spellcheck="false">${esc(state.edit?.recipe?JSON.stringify(state.edit.recipe,null,2):'')}</textarea></label><details class="int-details" open><summary>API 인증 정보</summary><div class="form-grid"><label class="field">토큰 (Bearer)<input name="credential_token" type="password" autocomplete="off" placeholder="빈칸이면 저장된 값 유지"></label><label class="field">API 키 (Header)<input name="credential_apiKey" type="password" autocomplete="off" placeholder="빈칸이면 저장된 값 유지"></label><label class="field">사용자 이름 (Basic)<input name="credential_username" autocomplete="off"></label><label class="field">비밀번호 (Basic)<input name="credential_password" type="password" autocomplete="off"></label></div><label class="field int-top-gap">로그인 세션 (Cookie)<input name="credential_cookie" type="password" autocomplete="off"></label><label class="field int-top-gap">추가 인증 항목 (JSON, 선택)<textarea name="extraCredentials" class="int-code" rows="3" placeholder='{"customToken":"직접 입력"}' spellcheck="false"></textarea></label><p class="help">인증값은 연결 규칙에 직접 넣지 말고 이 칸에 입력해주세요. 저장된 인증값은 다시 표시되지 않습니다.</p></details>`;
  }
  function connectionFields(){const form=$('[data-integrations="connection"]');if(!form)return;const p=provider(form.elements.providerId.value),mode=form.elements.mode.value;if(!p)return;form.querySelector('[data-connection-fields]').innerHTML=credentialFields(p,mode);}
  function modes(p,current){const options=[...(p.sessionApi?[['session','지마켓·옥션 API · 브라우저 세션 연결']]:[]),...(p.official?[['official','공식 API · 주문 수집 구현']]:[]),...(p.browserUrl?[['browser','브라우저 도우미 · 직접 로그인']]:[]),['api','API 규칙 직접 연결']];return options.map(([key,label])=>`<option value="${key}"${key===current?' selected':''}>${esc(label)}</option>`).join('');}
  async function connectionDialog(providerId,id){
    if(!state.providers.length)await load();state.edit=id?connection(id):null;const current=state.edit;
    const p=provider(current?.providerId||providerId)||state.providers.find(p=>p.official)||state.providers[0];if(!p)throw Error('연결할 대상 목록이 없습니다.');
    const mode=current?.mode||(p.sessionApi?'session':p.official?'official':p.browserUrl?'browser':'api');
    ui().openDialog(current?'연결 계정 설정':'새 계정 연결',`<form data-integrations="connection" class="int-dialog"><div class="form-grid"><label class="field">쇼핑몰 · 배송대행지<select name="providerId" required>${state.providers.map(x=>`<option value="${esc(x.id)}"${x.id===p.id?' selected':''}>${esc(x.name)} · ${kindLabel(x.kind)}</option>`).join('')}</select></label><label class="field">사업자<select name="businessId"><option value="">사업자 선택</option>${ui().businesses().map(b=>`<option value="${esc(b.id)}" ${current&&ui().businessFor(current.channel,current.name)===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><label class="field">계정 이름<input name="name" required maxlength="100" value="${esc(current?.name||p.name+' 기본 계정')}" placeholder="예: 쿠팡 1사업자"></label><label class="field wide">연결 방식<select name="mode">${modes(p,mode)}</select></label></div><div data-connection-fields class="int-fields">${credentialFields(p,mode)}</div><div class="form-error" data-integration-error role="alert"></div><div class="form-actions">${action('close','취소')}<button class="btn primary" type="submit">연결 정보 저장</button></div></form>`,{wide:true,kicker:'CONNECT ACCOUNTS'});
  }
  async function esmSessionDialog(id){
    await load();const c=connection(id);if(!c||c.mode!=='session')throw Error('ESM 연결 계정을 선택해주세요.');
    const request=await ui().api('/api/connections/'+encodeURIComponent(id)+'/session-request',{});
    ui().openDialog('지마켓·옥션 브라우저 연결',`<div class="int-dialog"><div class="info-box"><b>${esc(c.name)} · ${esc(c.channel)} · ${esc(c.sellerId)}</b><br>연결 요청은 ${esc(time(request.expiresAt))}까지 한 번 사용할 수 있습니다.</div><ol class="int-top-gap"><li>브라우저 도우미를 설치하고 이 프로그램과 페어링합니다.</li><li>ESM에서 해당 판매자 계정으로 직접 로그인합니다.</li><li>도우미의 ‘ESM 세션 연결’에서 이 계정을 선택하고 세션 저장을 확인합니다.</li></ol><p class="help">ESM 로그인 세션을 확인한 뒤 Windows 암호화 저장소에 보관합니다. 조회 중 받은 세션 갱신도 저장하며, 로그인 만료 시 다시 연결합니다.</p><div class="actions-inline">${link('https://www.esmplus.com','ESM 로그인 열기')}<a class="btn small" href="/api/browser-helper/download" download>도우미 다운로드</a>${action('pairDialog','설치 · 페어링 안내')}</div><div class="form-actions">${action('close','닫기')}${action('esmSessionStatus','연결 상태 확인',`data-id="${esc(id)}"`,'primary')}</div></div>`,{wide:true,kicker:'CONNECT ESM'});
  }
  async function collectDialog(id,tracking=false){
    await load();const options=state.connections.filter(c=>c.kind===(tracking?'forwarder':'market')&&c.mode!=='browser'&&(c.mode!=='session'||c.hasCredentials));
    if(!options.length){ui().openDialog(tracking?'송장 회수':'주문 수집',`<div class="info-box">${tracking?'송장 조회 API를 설정한 배송대행지 계정':'공식 API 또는 주문수집 API를 설정한 쇼핑몰 계정'}을 먼저 연결해주세요. 브라우저 계정은 로그인한 페이지에서 도우미로 가져옵니다.</div><div class="form-actions">${action('connectionAdd','계정 연결')}${action('pairDialog','브라우저 도우미')}</div>`,{kicker:'COLLECT ORDERS'});return;}
    ui().openDialog(tracking?'배송대행지 송장 회수':'쇼핑몰 주문 수집',`<form data-integrations="collect" data-tracking="${tracking}" class="int-dialog"><p class="help">선택한 계정을 순서대로 조회합니다.${tracking?' 접수번호 또는 주문번호가 맞는 신청의 송장을 등록합니다.':' 모든 페이지를 받은 계정만 주문을 저장합니다. 작업 메모와 보류 설정을 유지합니다.'}</p><div class="int-checklist">${options.map(c=>`<label class="check-label"><input type="checkbox" name="connectionIds" value="${esc(c.id)}"${(!id||id===c.id)&&!c.busy?' checked':''}${c.busy?' disabled':''}><span>${esc(c.name)} <small>${esc(c.channel)} · ${esc(modeLabel(c.mode))}</small></span></label>`).join('')}</div><div class="form-grid"><label class="field">조회 시작일<input name="from" type="date" value="${weekAgo()}" required></label><label class="field">조회 종료일<input name="to" type="date" value="${today()}" required></label></div><p class="help">쿠팡·스마트스토어는 최대 31일입니다. 스마트스토어는 최종 변경일 기준으로 조회합니다.</p><div id="integrationCollectResults" class="int-results" aria-live="polite"></div><div class="form-error" data-integration-error role="alert"></div><div class="form-actions">${action('close','닫기')}<button class="btn primary" type="submit">${tracking?'송장 조회':'주문 수집'} 시작</button></div></form>`,{wide:true,kicker:tracking?'RETURN TRACKING':'COLLECT ORDERS'});
  }
  function forwardingHtml(){
    const forwarders=state.connections.filter(c=>c.kind==='forwarder');
    return head('배송대행 작업실','주문을 묶어 신청서를 준비하고, 접수번호와 송장을 관리하세요.',action('collectDialog','송장 회수','data-tracking="true"')+action('forwardCreate','선택 주문으로 신청 초안','', 'primary'))+
      `<div class="int-metrics"><div><span>작성 중</span><strong>${state.drafts.filter(d=>d.state==='작성중').length}<small>건</small></strong><p>검토 후 API 또는 브라우저에서 신청합니다.</p></div><div><span>접수 · 송장 관리</span><strong>${state.drafts.filter(d=>['신청완료','송장회수'].includes(d.state)).length}<small>건</small></strong><p>확인한 접수번호와 배송 정보를 보관합니다.</p></div><div><span>결과 확인 필요</span><strong>${state.drafts.filter(d=>['결과미확인','전송중'].includes(d.state)).length}<small>건</small></strong><p>대행지에서 접수를 확인한 뒤 등록합니다.</p></div></div>`+
      `<section class="panel content-panel int-section"><div class="int-section-head"><div><h2>신청서 준비</h2><p class="help">통합 주문에서 품목을 선택한 뒤 ‘배송대행 신청’을 누르면 수령인별 초안이 만들어집니다.</p></div>${action('chooseOrders','주문 선택하기')}</div>${forwarders.length?`<div class="actions-inline">${forwarders.map(c=>`<span class="channel-tag">${esc(c.name)} · ${esc(modeLabel(c.mode))}</span>`).join('')}</div>`:`<div class="info-box">배송대행지 계정을 먼저 연결해주세요. 브라우저 신청서 또는 직접 확인한 API 규칙을 사용합니다.</div><p>${action('connectionAdd','배송대행지 연결','data-kind="forwarder"')}</p>`}</section>`+
      `<section class="panel int-section"><div class="int-catalog-head"><h2>배송신청 목록</h2><p class="help">접수 결과를 확인하지 못한 신청은 재전송할 수 없습니다.</p></div>${state.drafts.length?`<div class="table-wrap"><table><thead><tr><th>배송대행지</th><th>수령인</th><th>품목</th><th>진행 상태</th><th>접수번호 · 송장</th><th>생성일</th><th></th></tr></thead><tbody>${state.drafts.map(d=>`<tr><td>${esc(connection(d.connectionId)?.name||'대행지')}</td><td>${esc(d.recipient)}<span class="secondary">${esc(d.phone)}</span></td><td>${(d.items||[]).length}품목</td><td><span class="int-state${d.state==='결과미확인'?' error':''}">${esc(d.state)}</span></td><td>${esc(d.applicationId||'접수번호 미등록')}<span class="secondary">${esc(d.tracking||'송장 대기')} ${esc(d.carrier)}</span></td><td>${esc(time(d.createdAt))}</td><td>${action('forwardDetail','검토',`data-id="${esc(d.id)}"`,'small')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="int-empty">배송신청 초안이 없습니다. 통합 주문에서 배송할 품목을 선택해주세요.</div>'}</section>`+runsHtml();
  }
  function itemTable(items){return `<div class="preview-table"><table><thead><tr><th>주문번호</th><th>상품 · 옵션</th><th>수량</th><th>주문금액</th></tr></thead><tbody>${items.map(o=>`<tr><td>${esc(o.orderNo)}${o.demo?'<span class="pill demo">예제</span>':''}</td><td class="int-wrap">${esc(o.product)}<span class="secondary">${esc(o.option)}</span></td><td>${Number(o.quantity||0)}</td><td>${esc(ui().money(o.amount))}</td></tr>`).join('')}</tbody></table></div>`;}
  function draftEditHtml(d){
    if(d.state!=='작성중')return '';
    return `<details class="int-details"><summary>이 수령인의 통관번호 · 창고 · 신청 메모 수정</summary><form data-integrations="forwardEdit" data-id="${esc(d.id)}" data-version="${d.version}"><div class="form-grid"><label class="field">개인통관고유부호<input name="customsCode" maxlength="100" value="${esc(d.customsCode)}" placeholder="${esc(d.recipient)}님의 통관번호"></label><label class="field">대행 창고<input name="warehouse" maxlength="200" value="${esc(d.warehouse)}" placeholder="예: 미국 뉴저지"></label><label class="field wide">신청 메모<textarea name="memo" maxlength="2000">${esc(d.memo)}</textarea></label></div><p class="help">이 초안의 수령인 정보만 수정합니다. 다른 수령인의 신청에는 적용되지 않습니다.</p><div class="form-error" data-integration-error role="alert"></div><div class="form-actions"><button class="btn primary" type="submit">초안 정보 저장</button></div></form></details>`;
  }
  async function forwardCreate(){
    const ids=Array.from(ui().selected());if(!ids.length)throw Error('통합 주문에서 배송할 품목을 선택해주세요.');if(ids.length>100)throw Error('배송신청은 한 번에 100품목까지 선택해주세요.');
    await load();const forwarders=state.connections.filter(c=>c.kind==='forwarder');if(!forwarders.length){await connectionDialog(state.providers.find(p=>p.kind==='forwarder')?.id);return;}
    const orders=[];for(let i=0;i<ids.length;i+=10){const rows=await Promise.all(ids.slice(i,i+10).map(id=>ui().api('/api/orders/'+encodeURIComponent(id))));orders.push(...rows.map(r=>r.order));}
    if(orders.some(o=>!o||o.onHold||o.status==='취소'))throw Error('보류·취소 주문은 신청에서 제외해주세요.');
    state.pendingOrders=orders;const groups=new Map();for(const o of orders){const key=JSON.stringify([o.recipient,o.phone,o.postcode,o.address]);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(o);}const multi=groups.size>1;
    ui().openDialog('배송대행 신청 초안 만들기',`<form data-integrations="forwardCreate" class="int-dialog"><div class="info-box">선택 ${orders.length}품목 · 수령인 ${groups.size}명. 수령인이 다르면 신청 초안을 나누어 저장합니다.</div><label class="field int-top-gap">배송대행지<select name="connectionId" required>${forwarders.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${esc(modeLabel(c.mode))}</option>`).join('')}</select></label><div class="int-review-groups">${[...groups.values()].map(g=>`<section><h3>${esc(g[0].recipient||'수령인 미입력')} · ${g.length}품목</h3><p class="help">${esc(g[0].phone)}<br>(${esc(g[0].postcode)}) ${esc(g[0].address)}</p>${itemTable(g)}</section>`).join('')}</div><div class="form-grid"><label class="field">대행 창고<input name="warehouse" maxlength="200" placeholder="예: 미국 뉴저지"></label><label class="field">개인통관고유부호 (선택)<input name="customsCode" maxlength="100" ${multi?'disabled placeholder="초안 저장 후 수령인별로 각각 입력"':'placeholder="해당 수령인의 통관번호"'}></label><label class="field wide">신청 메모<textarea name="memo" maxlength="2000"></textarea></label></div>${multi?'<p class="help">초안을 저장한 뒤 각 신청의 검토 화면에서 수령인별 통관번호를 입력해주세요.</p>':''}${orders.some(o=>o.demo)?'<p class="int-error">예제 주문이 포함되어 있습니다. 실제 대행지에 신청하기 전에 실제 주문으로 교체해주세요.</p>':''}<label class="check-label int-top-gap"><input type="checkbox" required name="reviewed">수령인·주소·품목과 배송대행지를 확인했습니다.</label><div class="form-error" data-integration-error role="alert"></div><div class="form-actions">${action('close','취소')}<button class="btn primary" type="submit">초안 저장</button></div></form>`,{wide:true,kicker:'PREPARE FULFILLMENT'});
  }
  async function forwardDetail(id){
    state.drafts=arr(await ui().api('/api/forwarding'),'drafts');const d=state.drafts.find(x=>x.id===id);if(!d)throw Error('배송신청 초안을 찾을 수 없습니다.');const c=connection(d.connectionId)||{},p=provider(c.providerId)||{};
    const canSubmit=d.state==='작성중'&&c.mode==='api'&&Boolean(c.recipe?.operations?.submit);
    const caution=d.state==='결과미확인'?'<div class="int-warning">전송 결과를 확인하지 못했습니다. 대행지에서 실제 접수 여부를 먼저 확인한 뒤 접수번호를 등록해주세요. 중복 신청을 막기 위해 재전송을 차단했습니다.</div>':d.state==='전송중'?'<div class="info-box">전송 중입니다. 완료 후 목록을 새로 확인해주세요.</div>':d.state==='보관됨'?'<div class="info-box">보관된 초안입니다. 기록을 조회할 수 있으며 신청 전송·정보 수정·브라우저 신청서 채우기는 사용할 수 없습니다.</div>':'';
    ui().openDialog('배송신청 검토',`<div class="int-dialog"><div class="detail-summary"><strong>${esc(c.name||'배송대행지')}</strong><span class="int-state">${esc(d.state)}</span></div>${caution}<dl class="int-facts"><div><dt>수령인</dt><dd>${esc(d.recipient)} · ${esc(d.phone)}</dd></div><div><dt>배송지</dt><dd>(${esc(d.postcode)}) ${esc(d.address)}</dd></div><div><dt>창고</dt><dd>${esc(d.warehouse||'미입력')}</dd></div><div><dt>통관번호</dt><dd>${esc(d.customsCode||'미입력')}</dd></div><div><dt>배송메모</dt><dd>${esc(d.deliveryMemo||'없음')}</dd></div><div><dt>신청 메모</dt><dd>${esc(d.memo||'없음')}</dd></div><div><dt>접수번호</dt><dd>${esc(d.applicationId||'미등록')}</dd></div><div><dt>송장</dt><dd>${esc(d.carrier)} ${esc(d.tracking||'미등록')}</dd></div></dl>${itemTable(d.items||[])}${draftEditHtml(d)}<div class="actions-inline int-top-gap"><a class="btn" href="/api/forwarding/${encodeURIComponent(d.id)}/export">신청 CSV 내려받기</a>${d.state==='보관됨'?'':link(p.browserUrl,'대행지 신청 페이지 열기','btn')+action('pairDialog','브라우저 도우미 안내')}${d.state==='작성중'?action('forwardArchive','초안 보관',`data-id="${esc(d.id)}"`):''}</div>${canSubmit?`<form data-integrations="forwardSubmit" data-id="${esc(d.id)}" data-version="${d.version}"><label class="check-label int-top-gap"><input type="checkbox" name="confirmed" required>위 내용으로 배송대행지에 실제 신청을 전송합니다.</label><div class="form-error" data-integration-error role="alert"></div><div class="form-actions"><button class="btn primary" type="submit">배송신청 전송</button></div></form>`:d.state==='작성중'?'<p class="help">확인된 배송신청 API 규칙이 없습니다. 신청 페이지에서 도우미로 입력하거나 CSV 파일을 활용해 직접 신청해주세요.</p>':''}${!['전송중','보관됨'].includes(d.state)?`<details class="int-details"><summary>확인한 접수번호 · 송장 등록</summary><form data-integrations="receipt" data-id="${esc(d.id)}" data-version="${d.version}"><div class="form-grid"><label class="field wide">대행지 접수번호<input name="applicationId" required maxlength="200" value="${esc(d.applicationId)}"></label><label class="field">택배사 (선택)<input name="carrier" value="${esc(d.carrier)}"></label><label class="field">송장번호 (선택)<input name="tracking" value="${esc(d.tracking)}" spellcheck="false"></label></div><label class="check-label int-top-gap"><input type="checkbox" name="confirmed" required>대행지 화면에서 접수번호와 배송 정보를 확인했습니다.</label><div class="form-error" data-integration-error role="alert"></div><div class="form-actions"><button class="btn primary" type="submit">접수 결과 저장</button></div></form></details>`:''}</div>`,{wide:true,kicker:'REVIEW FULFILLMENT'});
  }
  async function pairDialog(){
    ui().openDialog('브라우저 연결 도우미',`<div class="int-dialog"><div class="info-box">브라우저에서 직접 로그인하고, 주문 목록이나 배송신청서를 연 뒤 필요한 동작을 눌러주세요. 도우미가 로그인·추가 인증·최종 신청을 자동으로 실행하지 않습니다.</div><ol class="int-instructions"><li><a href="/api/browser-helper/download">브라우저 도우미 파일 내려받기</a> → 압축을 풀어 Chrome 또는 Edge의 확장 관리 화면에서 ‘압축해제된 확장’을 불러옵니다.</li><li>아래에서 연결 코드를 만들고 도우미 화면에 입력합니다.</li><li>현재 계정과 페이지를 확인한 뒤 ‘현재 화면 수집’ 또는 ‘신청서 채우기’를 직접 실행합니다. 수집 결과와 신청 내용은 저장 전에 검토합니다.</li></ol><div id="integrationPairBox" class="int-pair-box" aria-live="polite">${state.pair?pairHtml():'<p class="help">연결 코드는 아직 만들지 않았습니다.</p>'}</div><div class="form-actions">${action('close','닫기')}${action('pairCode','연결 코드 만들기','','primary')}</div></div>`,{wide:true,kicker:'BROWSER HELPER'});
  }
  function pairHtml(){return `<label class="field">브라우저 도우미 연결 코드<input id="integrationPairCode" readonly value="${esc(state.pair.code)}" autocomplete="off" aria-label="도우미 연결 코드"></label><p class="help">만료: ${esc(time(state.pair.expiresAt))}. 이 PC의 도우미 화면에만 입력해주세요.</p>${action('pairCopy','코드 복사','','small')}`;}
  function archiveDialog(id){
    const d=state.drafts.find(x=>x.id===id);if(!d||d.state!=='작성중')throw Error('작성 중인 초안만 보관할 수 있습니다.');
    ui().openDialog('초안 보관 확인',`<div class="int-dialog"><div class="info-box">이 PC의 초안을 보관합니다. 외부 배송신청을 취소하는 동작은 아닙니다.</div><p class="help">${esc(d.recipient)}님의 ${(d.items||[]).length}품목 초안은 ‘보관됨’으로 목록에 남습니다. 이후 해당 주문으로 새 초안을 만들 수 있습니다.</p><div class="form-actions">${action('forwardDetail','돌아가기',`data-id="${esc(d.id)}"`)}${action('archiveConfirm','초안 보관',`data-id="${esc(d.id)}" data-version="${d.version}"`,'primary')}</div></div>`,{kicker:'ARCHIVE LOCAL DRAFT'});
  }
  async function busyButton(button,task,label='처리 중…'){
    const old=button?.innerHTML;if(button){button.disabled=true;button.classList.add('int-busy');button.textContent=label;}
    try{return await task();}finally{if(button?.isConnected){button.disabled=false;button.classList.remove('int-busy');button.innerHTML=old;}}
  }
  async function handleAction(button){
    const name=button.dataset.integrationAction,id=button.dataset.id;
    if(name==='close')close();
    else if(name==='refresh')await render(state.view);
    else if(name==='catalogMore'){state.limit+=30;renderCatalog();}
    else if(name==='connectionAdd'){let p=button.dataset.provider;if(!p&&button.dataset.kind==='forwarder')p=state.providers.find(x=>x.kind==='forwarder')?.id;await connectionDialog(p);}
    else if(name==='connectionEdit')await connectionDialog(null,id);
    else if(name==='esmSessionDialog')await esmSessionDialog(id);
    else if(name==='esmSessionStatus')await busyButton(button,async()=>{await load();const c=connection(id);if(c?.hasCredentials&&c.state==='인증 확인됨'){close();await render('connections');ui().toast('ESM 세션과 판매자 계정 연결을 확인했습니다.');}else ui().toast(c?.lastError||'브라우저 도우미에서 세션 연결을 마친 뒤 다시 확인해주세요.',true);},'상태 확인 중…');
    else if(name==='connectionTest')await busyButton(button,async()=>{await ui().api('/api/connections/'+encodeURIComponent(id)+'/test',{});ui().toast('인증과 읽기 응답을 확인했습니다.');await render(state.view);},'인증 확인 중…');
    else if(name==='collectDialog'||name==='trackingDialog')await collectDialog(id,name==='trackingDialog'||button.dataset.tracking==='true');
    else if(name==='recipeExample'){const example=await ui().api('/api/integrations/recipe-example?kind='+encodeURIComponent(button.dataset.kind||'market'));$('[data-integrations="connection"] [name="recipe"]').value=JSON.stringify(example.recipe||example,null,2);}
    else if(name==='forwardCreate')await busyButton(button,forwardCreate,'주문 확인 중…');
    else if(name==='forwardDetail')await forwardDetail(id);
    else if(name==='forwardArchive')archiveDialog(id);
    else if(name==='archiveConfirm')await busyButton(button,async()=>{await ui().api('/api/forwarding/'+encodeURIComponent(id)+'/archive',{expectedVersion:Number(button.dataset.version)});await forwardDetail(id);await ui().refresh();ui().toast('초안을 보관했습니다. 같은 주문으로 새 초안을 만들 수 있습니다.');},'보관 중…');
    else if(name==='chooseOrders')ui().go('orders');
    else if(name==='pairDialog')await pairDialog();
    else if(name==='pairCode')await busyButton(button,async()=>{state.pair=await ui().api('/api/bridge/pair-code',{});if(!state.pair.code)throw Error('연결 코드를 받지 못했습니다.');const box=$('#integrationPairBox');if(box)box.innerHTML=pairHtml();},'코드 만드는 중…');
    else if(name==='pairCopy'){const input=$('#integrationPairCode');if(!input)return;input.focus();input.select();try{await navigator.clipboard.writeText(input.value);ui().toast('연결 코드를 복사했습니다.');}catch{ui().toast('코드가 선택됐습니다. Ctrl+C로 복사해주세요.');}}
  }
  document.addEventListener('click',event=>{const button=event.target.closest('[data-integration-action]');if(!button||button.disabled)return;event.preventDefault();ui().run(()=>handleAction(button));});
  document.addEventListener('input',event=>{if(event.target.id==='integrationSearch'){state.query=event.target.value;state.limit=30;renderCatalog();}});
  document.addEventListener('change',event=>{
    const el=event.target;
    if(el.id==='integrationKind'){state.kind=el.value;state.limit=30;renderCatalog();}
    else if(el.id==='integrationReadiness'){state.readiness=el.value;state.limit=30;renderCatalog();}
    const form=el.closest('[data-integrations="connection"]');if(!form)return;
    if(el.name==='providerId'){const p=provider(el.value);form.elements.mode.innerHTML=modes(p,p.sessionApi?'session':p.official?'official':p.browserUrl?'browser':'api');connectionFields();}
    else if(el.name==='mode')connectionFields();
  });
  document.addEventListener('submit',event=>{
    const form=event.target.closest('form[data-integrations]');if(!form)return;event.preventDefault();
    ui().run(async()=>{const button=form.querySelector('button[type="submit"]');await busyButton(button,async()=>{
      const error=form.querySelector('[data-integration-error]');if(error)error.textContent='';
      try{
        if(form.dataset.integrations==='connection'){
          const credentials={};for(const input of form.querySelectorAll('[name^="credential_"]'))if(input.value.trim())credentials[input.name.slice(11)]=input.value.trim();
          const extra=form.elements.extraCredentials?.value.trim();if(extra){const obj=JSON.parse(extra);if(!obj||typeof obj!=='object'||Array.isArray(obj)||Object.values(obj).some(v=>typeof v!=='string'))throw Error('추가 인증 항목은 문자열 값의 JSON 객체로 입력해주세요.');Object.assign(credentials,obj);}
          const payload={...(state.edit?{id:state.edit.id}:{}),providerId:form.elements.providerId.value,name:form.elements.name.value.trim(),mode:form.elements.mode.value,credentials,businessId:form.elements.businessId.value};if(payload.mode==='api')payload.recipe=JSON.parse(form.elements.recipe.value);if(payload.mode==='session'){payload.site=form.elements.sessionSite.value;payload.sellerId=form.elements.sellerId.value.trim();}
          const saved=await ui().api('/api/connections',payload);close();await ui().reloadBoot();await ui().refresh();if(payload.mode==='session'&&!saved.hasCredentials)await esmSessionDialog(saved.id);else ui().toast(payload.mode==='browser'?'브라우저 연결을 저장했습니다. 로그인 후 도우미를 사용해주세요.':'연결 정보를 저장했습니다. 인증 확인을 실행해주세요.');
        }else if(form.dataset.integrations==='collect'){
          const ids=[...form.querySelectorAll('[name="connectionIds"]:checked')].map(el=>el.value);if(!ids.length)throw Error('수집할 계정을 선택해주세요.');const from=form.elements.from.value,to=form.elements.to.value;if(from>to)throw Error('조회 날짜 순서를 확인해주세요.');
          const tracking=form.dataset.tracking==='true',results=form.querySelector('#integrationCollectResults');let success=0;
          results.innerHTML=ids.map(id=>`<div data-result-id="${esc(id)}"><strong>${esc(connection(id)?.name)}</strong><span>대기 중</span></div>`).join('');
          for(const id of ids){const row=[...results.children].find(el=>el.dataset.resultId===id),label=row.querySelector('span');label.textContent='조회 중…';try{const result=await ui().api('/api/connections/'+encodeURIComponent(id)+(tracking?'/tracking':'/collect'),{from,to});label.textContent=summary(result.summary||result)+(result.notes?.length?' · '+result.notes.join(' '):'');row.classList.add('done');success++;}catch(e){label.textContent=e.message;row.classList.add('failed');}}
          await ui().reloadBoot();await ui().refresh();ui().toast(`${ids.length}계정 중 ${success}계정 수집 완료${success<ids.length?' · 실패 항목을 확인해주세요.':''}`,success<ids.length);
        }else if(form.dataset.integrations==='forwardCreate'){
          const result=await ui().api('/api/forwarding',{connectionId:form.elements.connectionId.value,orderIds:state.pendingOrders.map(o=>o.id),warehouse:form.elements.warehouse.value.trim(),customsCode:form.elements.customsCode.value.trim(),memo:form.elements.memo.value.trim()});close();ui().go('forwarding');ui().toast(`${arr(result,'drafts').length||result.created||1}개 배송신청 초안을 저장했습니다.`);
        }else if(form.dataset.integrations==='forwardEdit'){
          await ui().api('/api/forwarding/'+encodeURIComponent(form.dataset.id),{customsCode:form.elements.customsCode.value.trim(),warehouse:form.elements.warehouse.value.trim(),memo:form.elements.memo.value.trim(),expectedVersion:Number(form.dataset.version)},'PATCH');
          await forwardDetail(form.dataset.id);await ui().refresh();ui().toast('이 수령인의 통관번호와 초안 정보를 저장했습니다.');
        }else if(form.dataset.integrations==='forwardSubmit'){
          if(!form.elements.confirmed.checked)throw Error('배송신청 전송 확인을 선택해주세요.');await ui().api('/api/forwarding/'+encodeURIComponent(form.dataset.id)+'/submit',{expectedVersion:Number(form.dataset.version),confirmed:true});await forwardDetail(form.dataset.id);await render('forwarding');ui().toast('배송대행지 접수번호를 확인했습니다.');
        }else if(form.dataset.integrations==='receipt'){
          if(!form.elements.confirmed.checked)throw Error('대행지에서 확인한 정보인지 확인해주세요.');const carrier=form.elements.carrier.value.trim(),tracking=form.elements.tracking.value.trim();if(Boolean(carrier)!==Boolean(tracking))throw Error('택배사와 송장번호를 함께 입력해주세요.');await ui().api('/api/forwarding/'+encodeURIComponent(form.dataset.id)+'/receipt',{applicationId:form.elements.applicationId.value.trim(),carrier,tracking,expectedVersion:Number(form.dataset.version),confirmed:true});await forwardDetail(form.dataset.id);await ui().refresh();ui().toast('확인한 접수 결과를 저장했습니다.');
        }
      }catch(e){formError(form,e);if(form.dataset.integrations==='forwardSubmit'){await render('forwarding');ui().toast(e.message,true);}}
    });});
  });
  window.DobiIntegrations={render};
})();


  function renderBusinessSettings(){
    const section=nativeDocument.createElement('details');section.className='panel content-panel';
    section.innerHTML=`<summary>고급 · 주문 파일 계정·사업자 매핑</summary><p class="help">사업자를 등록하고 주문의 판매처·계정과 연결합니다.</p><form id="dobiBusiness"><div class="form-grid"><label class="field">사업자명<input name="name" required maxlength="120"></label><label class="field">사업자번호<input name="registrationNumber" maxlength="20"></label></div><div class="form-actions"><button class="btn primary">사업자 추가</button></div></form><form id="dobiBusinessLink"><div class="form-grid"><label class="field">판매 계정<select name="account">${state.boot.accounts.map(a=>`<option value="${esc(JSON.stringify([a.channel,a.name]))}">${esc(a.channel)} · ${esc(a.name)}</option>`).join('')}</select></label><label class="field">사업자<select name="businessId">${(state.boot.businesses||[]).map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('')}</select></label></div><div class="form-actions"><button class="btn">계정에 사업자 연결</button></div></form>`;
    $('#main').append(section);
    section.querySelector('#dobiBusiness').onsubmit=e=>{e.preventDefault();run(async()=>{await api('/api/businesses',Object.fromEntries(new FormData(e.target)));await reloadBoot();render();toast('사업자를 저장했습니다.');});};
    section.querySelector('#dobiBusinessLink').onsubmit=e=>{e.preventDefault();run(async()=>{const f=e.target,[channel,account]=JSON.parse(f.elements.account.value);await api('/api/account-business',{channel,account,businessId:f.elements.businessId.value});toast('사업자 연결을 저장했습니다.');});};
  }
  document.addEventListener('click',e=>{
    const a=e.target.closest('a[href]');if(a&&a.getAttribute('href').startsWith('/api/'))a.href=scopedUrl(a.getAttribute('href'));
    const row=e.target.closest('[data-order-row]');if(row&&!e.target.closest('button,input,select,a'))run(()=>orderDialog(row.dataset.orderRow));
  });
  document.addEventListener('keydown',e=>{const row=e.target.closest('[data-order-row]');if(row&&e.target===row&&e.key==='Enter')run(()=>orderDialog(row.dataset.orderRow));});
  for(const button of root.querySelectorAll('#nav [data-view]'))button.hidden=settingsOnly?!['connections','settings'].includes(button.dataset.view):['connections','settings'].includes(button.dataset.view);
  $('#nav').querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));
  const initializedForms=new WeakSet();let draftTimer,pendingDraft=null;
  function flushPendingDraft(){if(pendingDraft)void globalThis.fetch(scopedUrl('/api/drafts/'+pendingDraft.key),{method:'PUT',credentials:'same-origin',keepalive:true,headers:{'Content-Type':'application/json','X-Dobi-Token':state.boot?.token||''},body:JSON.stringify(pendingDraft.data)}).catch(()=>{});}
  async function draftKey(form){
    const type=form.id==='orderForm'?'order':form.dataset.integrations;
    const identity=type==='forwardCreate'?window.DobiUI.selected().sort().join(','):form.dataset.id||'new';
    const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(type+':'+identity));
    return 'form-'+[...new Uint8Array(bytes)].map(x=>x.toString(16).padStart(2,'0')).join('');
  }
  function draftValues(form){const values=Object.fromEntries([...new FormData(form)].filter(([k])=>form.elements.namedItem(k)?.type!=='password'));for(const el of form.elements)if(el.name&&el.type==='checkbox')values[el.name]=String(el.checked);return values;}
  async function attachDraft(form){
    if(initializedForms.has(form))return;initializedForms.add(form);
    const key=await draftKey(form);form.dataset.draftKey=key;
    const saved=await api('/api/drafts/'+key);
    if(saved&&String(saved.version??'')===String(form.dataset.version??''))for(const [name,value]of Object.entries(saved.values||{})){const el=form.elements.namedItem(name);if(el&&typeof value==='string'&&el.type!=='password'){if(el.type==='checkbox')el.checked=value==='true';else el.value=value;}}
    const button=nativeDocument.createElement('button');button.type='button';button.className='btn draft-save';button.textContent='임시 저장';
    const save=async()=>{const values=draftValues(form);await api('/api/drafts/'+key,{values,version:form.dataset.version||''},'PUT');button.textContent='임시 저장됨';};
    button.onclick=()=>run(save);(form.querySelector('.form-actions')||form).prepend(button);
    form.addEventListener('input',()=>{button.textContent='저장 대기';pendingDraft={key,data:{values:draftValues(form),version:form.dataset.version||''}};clearTimeout(draftTimer);draftTimer=setTimeout(()=>run(async()=>{await save();pendingDraft=null;}),500);});
  }
  const observer=new MutationObserver(()=>{if(disposed)return;for(const form of root.querySelectorAll('#orderForm,[data-integrations="forwardCreate"],[data-integrations="forwardEdit"]'))run(()=>attachDraft(form));});
  observer.observe(root,{childList:true,subtree:true});
  document.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.draftKey)return;setTimeout(()=>{if(!form.isConnected||!$('#dialog').open)run(()=>api('/api/drafts/'+form.dataset.draftKey,undefined,'DELETE'));},800);});
  run(async()=>{await reloadBoot();if(!disposed)await refresh();});
  return ()=>{if(pendingDraft)void globalThis.fetch(scopedUrl('/api/drafts/'+pendingDraft.key),{method:'PUT',credentials:'same-origin',keepalive:true,headers:{'Content-Type':'application/json','X-Dobi-Token':state.boot?.token||''},body:JSON.stringify(pendingDraft.data)}).catch(()=>{});disposed=true;observer.disconnect();for(const args of listeners)root.removeEventListener(...args);clearTimeout(searchTimer);clearTimeout(toastTimer);clearTimeout(draftTimer);};
}
